mapper.select:
SELECT 
    D.BOOKSET_ID
FROM 
    BOK_BATCH_TASK_TODO D
WHERE       
    D.SEQ_NO = #{seqNo,jdbcType=VARCHAR}
    AND D.BOOKSET_DATE = #{BOOKSET_DATE,jdbcType=DATE}
    AND D.BOOK_DATE = #{BOOK_DATE,jdbcType=DATE}
    AND D.HAPPEN_DATE = #{HAPPEN_DATE,jdbcType=DATE}
    AND D.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET,jdbcType=VARCHAR}
    AND D.TASK_ID = #{taskId,jdbcType=VARCHAR}
ORDER BY
    D.BOOKSET_ID

